<template>
  <div class="gallery-page"><div class="container page-head"><div><span class="eyebrow">MY CREATIONS</span><h1 class="serif">我的形象</h1><p>每一次描绘，都是想象留下的独特痕迹。</p></div><RouterLink to="/create" class="btn btn-primary"><el-icon><Plus /></el-icon>创作新形象</RouterLink></div>
    <div class="container gallery-toolbar"><div class="filter-tabs"><button v-for="t in ['全部作品','已定稿','未分类']" :key="t" :class="{active:filter===t}" @click="filter=t">{{ t }}</button></div><span>共 {{ assets.length }} 幅作品</span></div>
    <div class="container"><div v-if="loading" class="works-grid"><div v-for="i in 4" :key="i" class="work-skeleton skeleton"></div></div>
      <div v-else-if="assets.length" class="works-grid"><article v-for="(asset,i) in assets" :key="asset.id" class="work-card"><div class="work-image"><img :src="mediaUrl(asset.url)" :alt="asset.prompt||'我的 AI 形象'" loading="lazy"/><div class="work-overlay"><button @click="openAsset(asset)"><el-icon><FullScreen /></el-icon>查看大图</button></div><span class="work-tag">AI 创作</span></div><div class="work-info"><div><h3 class="serif">{{ asset.template_name || `东方意象 · ${String(i+1).padStart(2,'0')}` }}</h3><p>{{ date(asset.created_at) }}</p></div><el-dropdown><button class="more-btn"><el-icon><MoreFilled /></el-icon></button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="openAsset(asset)">查看详情</el-dropdown-item><el-dropdown-item @click="useAsset(asset)">去定制</el-dropdown-item><el-dropdown-item @click="download(asset)">下载作品</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></article></div>
      <div v-else class="empty-state"><div class="empty-art"><img src="/assets/product-scroll.svg" alt="空白画轴"/></div><span class="seal">镜</span><h2 class="serif">一纸空白，待你落笔</h2><p>从一句描述开始，生成你的第一幅专属形象。</p><RouterLink to="/create" class="btn btn-primary">开始 AI 创作<el-icon><ArrowRight /></el-icon></RouterLink></div>
    </div>
    <el-dialog v-model="dialogOpen" width="min(850px, 94vw)" class="art-dialog" :show-close="false"><div v-if="current" class="asset-detail"><div class="detail-image"><img :src="mediaUrl(current.url)" alt="AI 形象大图"/></div><div class="detail-copy"><span class="eyebrow">CREATION DETAIL</span><h2 class="serif">{{ current.template_name || '我的东方形象' }}</h2><p class="detail-date">{{ date(current.created_at) }} · AI 辅助生成</p><h4>创作描述</h4><p class="prompt-text">{{ current.prompt || '由镜绘东方风格模板生成，保留这一刻独特的想象。' }}</p><div class="detail-actions"><button class="btn btn-outline" @click="download(current)"><el-icon><Download /></el-icon>下载</button><button class="btn btn-primary" @click="useAsset(current)">定稿并去定制<el-icon><ArrowRight /></el-icon></button></div><button class="dialog-close icon-btn" @click="dialogOpen=false"><el-icon><Close /></el-icon></button></div></div></el-dialog>
  </div>
</template>
<script setup lang="ts">
import { onMounted, ref } from 'vue';import { useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import { aiApi, mediaUrl } from '@/services/api';import { date } from '@/utils/format';import type { MediaAsset } from '@/types'
const router=useRouter(),assets=ref<MediaAsset[]>([]),loading=ref(true),filter=ref('全部作品'),dialogOpen=ref(false),current=ref<MediaAsset|null>(null)
onMounted(async()=>{try{assets.value=await aiApi.assets()}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}})
function openAsset(a:MediaAsset){current.value=a;dialogOpen.value=true}
function useAsset(a:MediaAsset){localStorage.setItem('jinghui_draft',JSON.stringify({asset_id:a.id,image:mediaUrl(a.url),prompt:a.prompt,template:a.template_name}));router.push('/checkout')}
function download(a:MediaAsset){const link=document.createElement('a');link.href=mediaUrl(a.url);link.target='_blank';link.download=`镜绘作品-${a.id}.svg`;link.click()}
</script>
